typedef long long ll;

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int T;
    cin >> T;

    while(T--)
    {
        int n,m;
        cin >> n >> m;
        vector<int> a(n),b(m);
        for(int i=0;i<n;i++)
            cin >> a[i];

        int g=0;
        for(int i=0;i<m;i++)
        {
            cin >> b[i];
            g=__gcd(g,b[i]);
        }

        vector<vector<ll>> dp(g,vector<ll>(2));
        for(int i=0;i<g;i++)
            dp[i][1]=-2e9;
        for(int i=0;i<n;i++)
        {
            int rem=i%g;
            ll v0=max(dp[rem][0]+a[i],dp[rem][1]-a[i]);
            ll v1=max(dp[rem][0]-a[i],dp[rem][1]+a[i]);
            dp[rem][0]=v0;
            dp[rem][1]=v1;
        }

        ll sum0=0,sum1=0;
        for(int i=0;i<g;i++)
        {
            sum0+=dp[i][0];
            sum1+=dp[i][1];
        }

        cout << max(sum0,sum1) << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 1e6 + 100;

const int MOD = 998244353;

long long fact[MAXN];

long long F[MAXN];

long long qpow(long long a, long long b)
{
    long long res = 1;
    while(b)
    {
        if(b&1)res = res*a%MOD;
        a = a*a%MOD;
        b /= 2;
    }
    return res;
}

long long inv(long long x)
{
    return qpow(x,MOD-2);
}

int32_t main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    fact[0] = 1;

    for(int i = 1 ; i < MAXN ; i++)
    {
        fact[i] = fact[i-1]*i%MOD;
    }

    int T;
    cin >> T;

    while(T--)
    {
        int N;
        cin >> N;

        for(int i = 1 ; i <= N ; i++)
        {
            F[i] = 0;
        }

        for(int i = 1 ; i <= N ; i++)
        {
            int n;
            cin >> n;
            F[n]++;
        }

        vector<long long> vvv;

        for(int i = 1 ; i <= N ; i++)
        {
            if(F[i])vvv.push_back(F[i]);
        }

        int G = 0;

        for(auto x : vvv)
        {
            G = __gcd(G,x);
        }

        if(G == N)
        {
            cout << 1 << '\n';
            continue;
        }

        vector<long long> arr(N+1);
        vector<long long> arr2(N+1);

        for(int i = 1 ; i <= G ; i++)
        {
            if(G%i == 0)
            {
                long long tot = inv(fact[N/i-2]), acum = 0, sum = 0;

                for(auto x : vvv)
                {
                    tot = tot*fact[x/i]%MOD;
                    sum = (sum + acum*(x/i)*2)%MOD;
                    acum = (acum + (x/i))%MOD;
                }

                tot = inv(tot);

                arr2[i] = tot*(N/i-1)%MOD*(N/i)%MOD;

                tot = tot*sum%MOD*N%MOD;

                arr[i] = tot;
            }
        }

        long long res = 0;
        long long cont = 0;

        for(int i = 1 ; i <= N ; i++)
        {
            long long ggg = N/__gcd(N,i);

            if(G%ggg == 0)
            {
                res = (res + arr[ggg])%MOD;
                cont = (cont + arr2[ggg])%MOD;
            }
        }

        cout << res*inv(cont)%MOD << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct HOPCROFT_KARP
{
    int n, m;
    vector<vector<int>> adj;
    vector<int> mu, mv, level, que;

    HOPCROFT_KARP(int n, int m) : n(n), m(m), adj(n), mu(n, -1), mv(m, -1), level(n), que(n) {}

    void add_edge(int u, int v)
    {
        adj[u].push_back(v);
    }

    void bfs()
    {
        int qf = 0, qt = 0;
        for(int u = 0 ; u < n ; ++u)
        {
            if(mu[u] == -1)que[qt++] = u, level[u] = 0;
            else level[u] = -1;
        }
        for( ; qf < qt ; ++qf)
        {
            int u = que[qf];
            for(auto w : adj[u])
            {
                int v = mv[w];
                if(v != -1 && level[v] == -1)
                    que[qt++] = v, level[v] = level[u] + 1;
            }
        }
    }

    bool dfs(int u)
    {
        for(auto w : adj[u])
        {
            int v = mv[w];
            if(v == -1 || (level[v] == level[u] + 1 && dfs(v)))
                return mu[u] = w, mv[w] = u, true;
        }
        return false;
    }

    int max_matching()
    {
        int match = 0;
        for(int c = 1 ; bfs(), c ; match += c)
            for(int u = c = 0 ; u < n ; ++u)
                if(mu[u] == -1)
                    c += dfs(u);
        return match;
    }

    pair<vector<int>, vector<int>> min_vertex_cover()
    {
        max_matching();
        vector<int> L, R, inR(m);
        for(int u = 0 ; u < n ; ++u)
        {
            if(level[u] == -1)L.push_back(u);
            else if(mu[u] != -1)inR[mu[u]] = true;
        }
        for(int v = 0 ; v < m ; ++v)
            if(inR[v])R.push_back(v);
        return { L, R };
    }
};

const int MAXN = 5e4 + 100;

int arr[MAXN];
vector<int> dv[MAXN];

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    for(int i = 1 ; i < MAXN ; i++)
    {
        for(int j = i*2 ; j < MAXN ; j+=i)
        {
            dv[j].push_back(i);
        }
    }

    for(int i = 0 ; i < MAXN ; i++)
    {
        arr[i] = -1;
    }

    int T;
    cin >> T;

    while(T--)
    {
        int N;
        cin >> N;

        vector<int> vect;

        for(int i = 0 ; i < N ; i++)
        {
            int n;
            cin >> n;
            vect.push_back(n);
            arr[n] = i;
        }

        vector<pair<int,int>> edge;

        for(int i = 0 ; i < N ; i++)
        {
            for(auto x : dv[vect[i]])
            {
                if(arr[x] != -1)
                {
                    edge.push_back({i, arr[x]});
                }
            }
        }

        for(auto x : vect)
        {
            arr[x] = -1;
        }

        HOPCROFT_KARP HK(2*N,2*N);

        for(auto x : edge)
        {
            int i = x.first;
            int j = x.second;
            HK.add_edge(i,j);
            HK.add_edge(i+N,j+N);
        }

        for(int i = 0 ; i < N ; i++)
        {
            HK.add_edge(i+N,i);
        }

        cout << HK.max_matching()-N << '\n';
    }

    return 0;
}
